 je:[{q:'Customer owing ₹50,000 pays ₹49,000 in full settlement within 7 days.',e:'Bank A/c|49000\nDiscount Allowed A/c|1000\n>Customer A/c|50000',n:'cash received, ₹1,000 discount allowed for prompt payment'},{q:'Paid supplier ₹29,400 in full settlement of ₹30,000.',e:'Supplier A/c|30000\n>Bank A/c|29400\n>Discount Received A/c|600',n:'payment made, discount received'}],
